// The same layered model is used in live scenes, posters and reference sheets.
export const PALETTE={forest:'#24483C',sage:'#697F59',terracotta:'#AC6043',gold:'#DAA34E',burgundy:'#784C50',brown:'#B79D83',cream:'#F5ECDD'};
export const SKINS=['#F0C5A3','#D8A27E','#B77B58','#8D563D','#613D30'];
export const HAIRS=['#30271F','#574032','#845938','#A68A67','#353940'];
export const CLOTHES=['#697F59','#AC6043','#784C50','#24483C','#B79D83'];
export const escapeText=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function defaultCast(name='Alex'){return {version:1,player:{name,skin:SKINS[1],hair:HAIRS[0],hairstyle:'wave',clothing:CLOTHES[0],presentation:'androgynous',accessory:'none'},partner:{name:'Sam',skin:SKINS[2],hair:HAIRS[1],hairstyle:'bob',clothing:CLOTHES[1],presentation:'feminine',accessory:'none'}};}
export function castFor(state){return state.game?.characters||defaultCast(state.name);}
export function validateCharacter(c){return !!c&&typeof c.name==='string'&&c.name.trim().length>0&&c.name.length<=40&&SKINS.includes(c.skin)&&HAIRS.includes(c.hair)&&CLOTHES.includes(c.clothing)&&['wave','crop','bob','long'].includes(c.hairstyle)&&['feminine','masculine','androgynous'].includes(c.presentation)&&['none','glasses','earrings'].includes(c.accessory);}
export const SUPPORT={doctor:{name:'Dr. Hana',skin:SKINS[2],hair:HAIRS[0],hairstyle:'bob',clothing:'#F5ECDD',presentation:'feminine',accessory:'glasses'},mechanic:{name:'Ravi',skin:SKINS[3],hair:HAIRS[0],hairstyle:'crop',clothing:'#697F59',presentation:'masculine',accessory:'none'},agent:{name:'Mei',skin:SKINS[1],hair:HAIRS[1],hairstyle:'long',clothing:'#784C50',presentation:'feminine',accessory:'earrings'},contractor:{name:'Idris',skin:SKINS[3],hair:HAIRS[0],hairstyle:'wave',clothing:'#B79D83',presentation:'masculine',accessory:'glasses'},assistant:{name:'Ari',skin:SKINS[2],hair:HAIRS[0],hairstyle:'crop',clothing:'#AC6043',presentation:'androgynous',accessory:'none'},family:{name:'June',skin:SKINS[2],hair:HAIRS[3],hairstyle:'bob',clothing:'#784C50',presentation:'feminine',accessory:'glasses'}};
export function character(c,{id='player',x=0,y=0,scale=1,expression='neutral',pose='standing',view='front'}={}){
  const long=['bob','long'].includes(c.hairstyle),back=view==='back',side=view==='side',turn=view==='three-quarter'?9:0;
  const mouth=expression==='surprised'||expression==='confused'?'<ellipse cx="0" cy="-127" rx="4" ry="7"/>':expression==='worried'||expression==='disappointed'?'<path d="M-7-125 Q0-132 7-125" fill="none"/>':'<path d="M-8-129 Q0-119 8-129" fill="none"/>';
  return `<g class="actor actor-${id} pose-${pose} expression-${expression}" transform="translate(${x} ${y}) scale(${scale})" aria-label="${escapeText(c.name)}"><g class="actor-motion" transform="${side?'scale(.65 1)':view==='three-quarter'?'scale(.87 1)':''}"><ellipse cx="0" cy="0" rx="32" ry="5" fill="#30271F" opacity=".12"/><g class="legs" transform="${pose==='sitting'?'translate(0 -21) scale(1.1 .6)':''}" fill="#514E44"><path d="M-22-92L-23-8Q-19 1-8-5L-2-91Z"/><path d="M3-91L10-6Q20 0 24-8L22-93Z"/></g><g fill="#30271F"><path d="M-24-11Q-43-6-36 0H-9L-9-10Z"/><path d="M10-10L11 0H38Q42-7 25-11Z"/></g><g class="upper-body" transform="translate(0 -35)"><g class="body" fill="${c.clothing}" stroke="#403C32" stroke-width="1.2"><path d="${c.presentation==='feminine'?'M-16-117Q-34-106-24-82L-31-51Q0-42 32-52L24-82Q32-110 16-117Z':c.presentation==='masculine'?'M-17-117Q-40-109-32-78L-28-51Q0-46 30-52L33-80Q40-111 17-117Z':'M-16-117Q-36-107-30-78L-26-51Q0-43 28-52L31-80Q32-110 16-117Z'}"/><path d="M-25-101Q-13-91 23-97" opacity=".15" fill="none"/><path d="M-24-67Q0-60 24-65" opacity=".15" fill="none"/></g><g class="arm arm-left" style="transform-origin:-27px -103px"><path d="M-27-104Q-45-93-39-65L-33-48" fill="none" stroke="${c.clothing}" stroke-width="15" stroke-linecap="round"/><path d="M-33-51L-30-41" stroke="${c.skin}" stroke-width="11" stroke-linecap="round"/></g><g class="arm arm-right" transform="${['gesture','speaking'].includes(pose)?'rotate(-45 27 -103)':''}" style="transform-origin:27px -103px"><path d="M27-104Q42-87 34-63L29-47" fill="none" stroke="${c.clothing}" stroke-width="15" stroke-linecap="round"/><path d="M29-49L27-40" stroke="${c.skin}" stroke-width="11" stroke-linecap="round"/></g><g class="head" transform="translate(${turn} -24) scale(.8)"><g class="head-motion"><path d="M-6-119V-108Q0-102 8-110V-121" fill="${c.skin}"/><path d="M-25-145Q-29-176 0-178Q29-178 26-143L${long?(c.hairstyle==='long'?'33-78Q20-67 11-98H-15Q-30-71-32-80Z':'31-112Q17-107 12-119H-15Q-31-104-31-116Z'):'20-128H-21Z'}" fill="${c.hair}"/><ellipse cx="-23" cy="-140" rx="5" ry="8" fill="${c.skin}"/><ellipse cx="22" cy="-140" rx="5" ry="8" fill="${c.skin}"/><path d="M-23-154Q-22-171 0-169Q23-170 23-151L20-134Q14-117 0-118Q-15-117-22-136Z" fill="${back?c.hair:c.skin}" stroke="#634B3B" stroke-width=".8"/>${back?'':`<g class="face" transform="${side?'translate(8 0) scale(.65 1)':''}"><path class="brows" d="M-15-150Q-9-154-4-150M5-150Q11-154 16-149" fill="none" stroke="${c.hair}" stroke-width="2"/><g class="eyes" fill="#30271F"><ellipse cx="-10" cy="-143" rx="2" ry="3"/><ellipse cx="10" cy="-143" rx="2" ry="3"/></g><path d="M1-142L-1-135L3-134" fill="none" stroke="#94684E" stroke-width="1"/><g class="mouth" fill="#784C50" stroke="#784C50" stroke-width="1.5"><g class="mouth-base">${mouth}</g><path class="mouth-happy" display="none" d="M-9-130Q0-115 9-130Z" fill="#784C50"/><ellipse class="mouth-surprise" display="none" cx="0" cy="-127" rx="4" ry="7"/><path class="mouth-speaking" display="none" d="M-7-128Q0-119 7-128Z"/></g><ellipse cx="-15" cy="-134" rx="5" ry="2.5" fill="#AC6043" opacity=".19"/><ellipse cx="15" cy="-134" rx="5" ry="2.5" fill="#AC6043" opacity=".19"/>${c.accessory==='glasses'?'<g fill="none" stroke="#403C32" stroke-width="1.5"><rect x="-20" y="-150" width="17" height="13" rx="4"/><rect x="3" y="-150" width="17" height="13" rx="4"/><path d="M-3-145H3"/></g>':''}</g>`}<path d="${c.hairstyle==='crop'?'M-25-150Q-29-179 0-179Q28-180 26-150L16-163L-1-158L-14-163Z':c.hairstyle==='wave'?'M-24-147Q-33-166-15-175Q-3-185 11-173Q31-173 25-149Q17-152 11-163Q-7-153-20-161Z':'M-24-142Q-32-178-2-180Q28-181 26-144L17-160Q-7-151-18-163L-20-142Z'}" fill="${c.hair}"/><path d="M-19-168Q-5-178 10-169" fill="none" stroke="#F5ECDD" stroke-width="2" opacity=".12"/>${c.accessory==='earrings'?'<g fill="#DAA34E"><circle cx="-25" cy="-132" r="3"/><circle cx="25" cy="-132" r="3"/></g>':''}</g></g>${id==='doctor'?'<path d="M-13-108Q-20-86-6-84Q7-84 13-108M-6-84V-75" fill="none" stroke="#697F59" stroke-width="2"/><circle cx="-6" cy="-73" r="4" fill="#B79D83"/>':''}</g></g></g>`;
}
export function modelSheet(c,id){const expressions=['neutral','happy','surprised','worried','confused','disappointed','excited'];return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1100 760"><rect width="1100" height="760" fill="#F5ECDD"/><g font-family="Georgia" fill="#24483C"><text x="35" y="40" font-size="26">${escapeText(c.name)} · original layered model</text><text x="35" y="68" font-size="14">${id} / v1 · expressive storybook rig · same model in every scene</text>${['front','three-quarter','side','back'].map((v,n)=>character(c,{id,x:130+n*210,y:285,view:v})+`<text x="${95+n*210}" y="310" font-size="14">${v}</text>`).join('')}${expressions.map((e,n)=>character(c,{id,x:80+n*155,y:520,scale:.73,expression:e})+`<text x="${35+n*155}" y="550" font-size="13">${e}</text>`).join('')}${['speaking','sitting','standing','gesture'].map((p,n)=>character(c,{id,x:130+n*245,y:725,scale:.7,pose:p})+`<text x="${96+n*245}" y="748" font-size="13">${p}</text>`).join('')}</g></svg>`;}

Object.assign(SUPPORT,{nurse:{...SUPPORT.doctor,name:'Nurse Lin',hairstyle:'crop',clothing:'#B79D83',accessory:'none'},bankOfficer:{...SUPPORT.agent,name:'Daniel',presentation:'masculine',hairstyle:'crop',clothing:'#24483C'},weddingPlanner:{...SUPPORT.agent,name:'Nadia',skin:SKINS[3],clothing:'#AC6043'},supplier:{...SUPPORT.mechanic,name:'Amir',clothing:'#B79D83',hairstyle:'wave'},shopAssistant:{...SUPPORT.assistant,name:'Wei',skin:SKINS[1],accessory:'glasses'}});
export function babyCharacter({x=0,y=0,skin=SKINS[1],blanket='#697F59'}={}){return '<g class="baby-character" transform="translate('+x+' '+y+')"><path d="M-19 4Q-22 39 0 46Q22 39 19 4Z" fill="'+blanket+'" stroke="#784C50" stroke-width="1.5"/><path d="M-17 13L15 31M17 13L-11 38" fill="none" stroke="#F5ECDD" opacity=".4"/><circle cy="-3" r="15" fill="'+skin+'"/><path d="M-9-2Q-5 2-2-2M3-2Q6 2 10-2M-2 6Q1 9 4 6" stroke="#784C50" fill="none" stroke-width="1.4"/><path d="M-5-17Q5-23 5-14" stroke="#574032" fill="none" stroke-width="2"/></g>';}
export function babyModelSheet(){return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 680 220"><rect width="680" height="220" fill="#F5ECDD"/><text x="28" y="38" fill="#24483C" font-family="Georgia" font-size="22">Story babies · original swaddled model</text>'+[0,1,2,3].map(n=>babyCharacter({x:90+n*160,y:110,skin:SKINS[n],blanket:CLOTHES[n]})).join('')+'<text x="28" y="200" fill="#24483C" font-family="Georgia" font-size="13">Same reusable baby model; a persisted twins branch adds a second instance.</text></svg>';}
